$want = @('context:mixed-media-artists-playground','context:mixed-media-controlled-chaos','context:mixed-media-engraving-meets-the-future','context:mixed-media-eras-collide','context:mixed-media-material-collisions','context:mixed-media-nature-collides-with-design','context:mixed-media-photograph-memory-and-art','context:mixed-media-realism-collides-with-graphic-art','context:mixed-media-torn-worlds','context:mixed-media-typography-becomes-art')
$tmp = Join-Path $env:TEMP "aura-ctx-mixed-media.json"
ConvertTo-Json @($want) | Set-Content -Path $tmp -Encoding utf8
$out = (npx wrangler kv bulk get $tmp --namespace-id $ns --remote 2>$null | Out-String)
$hits = [regex]::Matches($out, '"(context:[^"]+)":\s*"((?:[^"\\]|\\.)*)"')
if ($hits.Count -eq 0) { "  none found" } else { foreach ($h in $hits) { "  removed " + $h.Groups[1].Value + ": " + $h.Groups[2].Value; npx wrangler kv key delete --namespace-id $ns $h.Groups[1].Value --remote 2>$null | Out-Null }; "  waiting 70 seconds"; Start-Sleep -Seconds 70 }
foreach ($c in $cats.Keys) { RUN ("REDO " + $final[$test[$c]]) }
}
}
}
